  transactionId.writeUInt16BE(0x1234, 0);

  const flags = Buffer.alloc(2);
  flags.writeUInt16BE(0x0100, 0); // Standard query

  const questions = Buffer.alloc(2);
  questions.writeUInt16BE(1, 0); // 1 question

